<script setup lang="ts">import type{OperationSummary}from'../../api/desktop';defineProps<{items:OperationSummary[];loading:boolean}>();defineEmits(['select'])</script><template><div v-loading="loading" class="list"><button v-for="i in items" :key="i.identifier" @click="$emit('select',i.identifier)"><span><b>{{i.search||'未记录规则'}} → {{i.replacement||'删除'}}</b><small>{{i.root}}</small></span><span><el-tag size="small">{{i.status}}</el-tag><small>{{i.successCount}} / {{i.itemCount}} 项</small></span></button><el-empty v-if="!loading&&!items.length" description="暂无操作日志"/></div></template><style scoped>.list{display:grid;align-content:start;gap:8px;overflow:auto}.list button{display:flex;justify-content:space-between;gap:16px;text-align:left;padding:14px;border:1px solid var(--border);border-radius:var(--radius);background:var(--surface);color:var(--text);cursor:pointer}.list button:hover{border-color:var(--primary)}span{display:grid;gap:6px;min-width:0}small{color:var(--muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}</style>
